import{_ as t,a,o,a4 as s}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"CMS Pages","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/cms/pages/index.md","filePath":"api/rest-api/admin/cms/pages/index.md","lastUpdated":1783420618000}'),i={name:"api/rest-api/admin/cms/pages/index.md"};function n(d,e,r,l,c,p){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="cms-pages" tabindex="-1">CMS Pages <a class="header-anchor" href="#cms-pages" aria-label="Permalink to &quot;CMS Pages&quot;">​</a></h1><p>CMS Pages are <strong>static storefront content pages</strong> — About Us, Privacy Policy, custom landing pages, and the like. Each page is served on the storefront at its <code>url_key</code> (e.g. <code>/page/about-us</code>). This menu mirrors the admin <strong>CMS → Pages</strong> screen: list, create, edit, delete, and export those pages.</p><h2 id="multi-locale-multi-channel" tabindex="-1">Multi-locale, multi-channel <a class="header-anchor" href="#multi-locale-multi-channel" aria-label="Permalink to &quot;Multi-locale, multi-channel&quot;">​</a></h2><p>A page is content that spans languages and storefronts:</p><ul><li><strong>Multi-locale</strong> — a page holds <strong>one content set per language</strong> (its <code>translations</code>). Each locale has its own <code>page_title</code>, <code>html_content</code>, <code>url_key</code>, and SEO fields. The listing/detail show the values for the resolved <code>locale</code>; the full per-locale set comes back under <code>translations</code> on the detail endpoint.</li><li><strong>Multi-channel</strong> — a page is <strong>assigned to one or more channels</strong> (storefronts). The detail endpoint returns the assigned <code>channels</code> as <code>{ id, code, name }</code> objects; the listing returns the channel codes as a <code>channels</code> string array.</li></ul><h2 id="previewurl-—-the-view-action" tabindex="-1"><code>previewUrl</code> — the &quot;View&quot; action <a class="header-anchor" href="#previewurl-—-the-view-action" aria-label="Permalink to &quot;`previewUrl` — the &quot;View&quot; action&quot;">​</a></h2><p>Every row carries a <code>previewUrl</code> — the storefront URL where the page actually renders (built from its <code>url_key</code>). This is the API equivalent of the admin <strong>View</strong> action: open it in a browser to preview the live page.</p><h2 id="htmlcontent-is-detail-only" tabindex="-1"><code>htmlContent</code> is detail-only <a class="header-anchor" href="#htmlcontent-is-detail-only" aria-label="Permalink to &quot;`htmlContent` is detail-only&quot;">​</a></h2><p><code>htmlContent</code> is the <strong>full page HTML body</strong>. It is <strong><code>null</code> on the listing</strong> (to keep rows light) and is returned only by the <a href="/api/rest-api/admin/cms/pages-detail.html">detail endpoint</a>. The listing carries every other cheap column (titles, url_key, SEO, layout, channels, timestamps).</p><h2 id="create-vs-update-payload-shapes" tabindex="-1">Create vs Update payload shapes <a class="header-anchor" href="#create-vs-update-payload-shapes" aria-label="Permalink to &quot;Create vs Update payload shapes&quot;">​</a></h2><p>The two write endpoints take <strong>different shapes</strong> (this mirrors the admin form):</p><ul><li><strong>Create</strong> sends <strong>top-level</strong> fields (<code>url_key</code>, <code>page_title</code>, <code>html_content</code>, <code>meta_*</code>, <code>channels</code>). Those values are <strong>broadcast to every configured locale</strong> at creation.</li><li><strong>Update</strong> sends a <strong>locale-nested</strong> body (<code>{ &quot;en&quot;: { url_key, page_title, ... }, &quot;channels&quot;: [...] }</code>) so you edit one locale at a time.</li></ul><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/cms/pages-list.html">List pages</a></td><td><code>GET /api/admin/cms/pages</code></td></tr><tr><td><a href="/api/rest-api/admin/cms/pages-detail.html">Page detail</a></td><td><code>GET /api/admin/cms/pages/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/cms/pages-create.html">Create page</a></td><td><code>POST /api/admin/cms/pages</code></td></tr><tr><td><a href="/api/rest-api/admin/cms/pages-update.html">Update page</a></td><td><code>PUT /api/admin/cms/pages/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/cms/pages-delete.html">Delete page</a></td><td><code>DELETE /api/admin/cms/pages/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/cms/pages-mass-delete.html">Mass delete pages</a></td><td><code>POST /api/admin/cms/pages/mass-delete</code></td></tr><tr><td><a href="/api/rest-api/admin/cms/pages/export.html">Export pages (CSV)</a></td><td><code>GET /api/admin/cms/pages/export</code></td></tr></tbody></table><p>All CMS Pages endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>. Writes require the matching <code>cms.create</code> / <code>cms.edit</code> / <code>cms.delete</code> permission.</p>',15)]))}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
